state = {}

def on_state(robot, seq, ts, battery):
    cur = state.get(robot)
    if cur and seq <= cur["seq"]:
        return "버림(옛 메시지)"
    state[robot] = {"seq": seq, "ts": ts, "battery": battery}
    return "반영"

msgs = [("amr-1", 41, 100.0, 63), ("amr-1", 43, 102.0, 61), ("amr-1", 42, 101.0, 62)]
for m in msgs:
    print(m, "→", on_state(*m))
print("현재:", state["amr-1"])

def status(robot, now, timeout=5.0):
    return "ONLINE" if now - state[robot]["ts"] <= timeout else "OFFLINE"

for now in (104.0, 107.5):
    print(f"t={now}: {status('amr-1', now)}")

# ('amr-1', 41, 100.0, 63) → 반영
# ('amr-1', 43, 102.0, 61) → 반영
# ('amr-1', 42, 101.0, 62) → 버림(옛 메시지)
# 현재: {'seq': 43, 'ts': 102.0, 'battery': 61}
# t=104.0: ONLINE
# t=107.5: OFFLINE
